IDs=['estetoscopio','jeringa','aguja','cateter-periferico','equipo-iv','bureta','llave-tres-vias','tensiometro','pulsioximetro','bomba-volumetrica','bomba-jeringa','monitor','canula-nasal','mascarilla-simple','mascarilla-reservorio','mascarilla-venturi','bvm','foley-dos-vias','foley-tres-vias','sonda-nasogastrica','tubo-endotraqueal','traqueostomia','cvc-triple','desfibrilador']

def make():
 staging=ROOT/'.cache/atlas-kawaii-final';staging.mkdir(parents=True,exist_ok=True)
 arts={a.id:a for a in [f() for f in ALL]}
 assert list(arts)==IDs and len(INVENT)==24
 records=[]; drawing_reviews=[]
 for idx,id in enumerate(IDs):
  art=arts[id]; result=art.export(staging); points=result['points']; row=INVENT[idx]
  drawing_reviews.append(dict(id=id,points=points,face_boxes_viewbox=result['face_boxes_viewbox'],rotation=result['rotation']))
  assert idx+1==row['number']
  namefile=row['requested_file'].replace('balón','balon');asset_id=Path(namefile).stem
  if id in OLD:
   old=OLD[id];parts=[dict(q) for q in old['parts']];sources=[dict(s) for s in old['sources']]
   if id=='llave-tres-vias':sources=[] # indexed-only URL replaced by fully retrieved sources
   sources+=EXTRA.get(id,[])
   name,technical=old['name'],old['technical_name']
   if id=='equipo-iv':
    parts[0].update(name='Punzón del equipo',part_description='Punzón del equipo',safety='La ilustración no demuestra que el dispositivo esté protegido ni sea estéril.')
   for q in parts:
    q['safety']=q['safety'].replace(' Recurso visual pendiente: no hay punto de identificación.','')
   parts+=NEWPART.get(id,[])
   note=MODEL[id]
  else:
   name,technical,note,parts,sources=NEW[id]
  assert len(sources)>=2,(id,sources)
  for q in parts:
   key=q['id'];visible=key in points and not (id=='traqueostomia' and key=='canula-interna')
   x,y=points.get(key,(None,None)) if visible else (None,None)
   q.update(hotspot_x=x,hotspot_y=y,visible=visible,source_urls=[s['url'] for s in sources],review_status='COTEJO-DOCUMENTAL-ASISTIDO; APROBACIÓN-PROFESIONAL-PENDIENTE')
   if visible:
    assert 0<=x<=1 and 0<=y<=1,(id,key)
    with Image.open(result['file']) as im:
     assert im.getpixel((int(x*2000),int(y*1250)))[3]>=128,(id,key,x,y)
  assert sum(q['visible'] and q['id']!='punta' for q in parts)>=2
  imagepath=ASSET/namefile;ASSET.mkdir(parents=True,exist_ok=True);shutil.copyfile(result['file'],imagepath)
  processing=dict(method='Ilustración 2D original creada por código; rasterización directa de geometría vectorial con CairoSVG 2.8.2. No es foto ni IA generativa de imagen.',native_dimensions=[2000,1250],export_dimensions=[2000,1250],upscaled=False,source_svg_sha256=result['source_sha256'],sha256=result['png_sha256'],reproducer='research/atlas_kawaii/ilustrar.py',face='Decorativa; no es parte clínica ni lectura.')
  d=dict(asset_id=asset_id,id=id,name=name,display_name_es=name,technical_name=technical,area='Dispositivos',file='atlas/'+namefile,view='Ilustración 2D educativa del conjunto, vista simplificada; no a escala',image_available=True,image_width=2000,image_height=1250,image_sha256=result['png_sha256'],alt_text=f'{technical}: ilustración kawaii en colores pastel, con cara decorativa. No es fotografía ni una lectura clínica. Partes disponibles en la lista accesible.',model_note=note,parts=parts,sources=sources,source_urls=[s['url'] for s in sources],review_date=DATE,review_status='COTEJO-ASISTIDO; APROBACIÓN-PROFESIONAL-PENDIENTE',accuracy_approved_by=None,technical_reviewer='Asistente IA: cotejo documental y visual, no profesional acreditado',clinical_approved=False,pending_reason='',processing=processing,checks=['Identificar el modelo y consultar sus instrucciones de uso.','Comprobar integridad y condiciones del producto real con personal capacitado.','La ilustración no confirma esterilidad, calibración, compatibilidad ni competencia técnica.'],revision='atlas-v22.1')
  records.append(d)
  (ASSET/(asset_id+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 # Only retire obsolete pending sidecars after all 24 current records have been successfully assembled.
 for f in ASSET.glob('pendiente_*.json'):f.unlink()
 (HERE/'registro_ilustraciones.json').write_text(json.dumps([dict(id=r['id'],file=r['file'],image_sha256=r['image_sha256'],source_svg_sha256=r['processing']['source_svg_sha256'],revision_dibujo=review) for r,review in zip(records,drawing_reviews)],ensure_ascii=False,indent=2)+'\n')
 print('24 PNG RGBA con metadatos; sin aprobación profesional; 2000 x 1250, sin reescalado fotográfico.')
if __name__=='__main__':make()
